style.css:
@-moz-document domain("crm.moreagency.digital") {
:root {
    --bg: #16161a;
    --bg-elevated: #1d1d22;
    --bg-card: #201f26;
    --border: #2c2b33;
    --text: #eae7de;
    --text-muted: #8f8b98;
    --accent: #c9a15a;
    --accent-contrast: #16161a;
    --success: #4fae7d;
    --danger: #c9695f;
  }

  body, .app {
    background: var(--bg) !important;
    color: var(--text) !important;
  }

  .sidebar {
    background: var(--bg-elevated) !important;
    border-right: 1px solid var(--border) !important;
  }

  .brand { color: var(--text) !important; }

  .sidebar a, .sidebar .nav-item, .sidebar li {
    color: var(--text-muted) !important;
  }

  .sidebar a.active, .sidebar .active, .sidebar li.active {
    background: rgba(201, 161, 90, 0.12) !important;
    color: var(--accent) !important;
    border-radius: 10px !important;
  }

  .task-block, .time-card, .props, .card, [class*="card"] {
    background: var(--bg-card) !important;
    border: 1px solid var(--border) !important;
    border-radius: 16px !important;
    box-shadow: 0 8px 24px rgba(0,0,0,0.35) !important;
  }

  .topbar-left, .topbar, header {
    background: var(--bg-elevated) !important;
    border-bottom: 1px solid var(--border) !important;
  }

  .btn, .btn-ghost {
    background: transparent !important;
    border: 1px solid var(--border) !important;
    color: var(--text) !important;
    border-radius: 10px !important;
  }
  .btn:hover, .btn-ghost:hover {
    border-color: var(--accent) !important;
    color: var(--accent) !important;
  }

  .btn-primary {
    background: linear-gradient(180deg, #d9b06c, #c9a15a) !important;
    color: var(--accent-contrast) !important;
    border: none !important;
    font-weight: 600 !important;
    box-shadow: 0 4px 14px rgba(201,161,90,0.25) !important;
  }
  .btn-primary:hover { filter: brightness(1.08) !important; }

  .tag-chip {
    background: var(--bg-elevated) !important;
    border: 1px solid var(--border) !important;
    color: var(--text-muted) !important;
  }

  ::-webkit-scrollbar { width: 10px; height: 10px; }
  ::-webkit-scrollbar-track { background: var(--bg); }
  ::-webkit-scrollbar-thumb { background: #35343c; border-radius: 8px; }
  ::-webkit-scrollbar-thumb:hover { background: #45434e; }

  a, .text-muted { transition: color .15s ease; }
}
